exercise.solution:
let tasks = [];

function handleRequest(request) {
  if (request.method === 'GET' && request.path === '/api/tasks') {
    return {
      status: 200,
      body: tasks
    };
  }

  if (request.method === 'POST' && request.path === '/api/tasks') {
    const title = request.body?.title;

    if (typeof title !== 'string' || title.trim() === '') {
      return {
        status: 400,
        body: { error: 'Title is required' }
      };
    }

    const newTask = {
      id: tasks.length + 1,
      title,
      done: false
    };

    tasks.push(newTask);

    return {
      status: 201,
      body: newTask
    };
  }

  return {
    status: 404,
    body: { error: 'Not found' }
  };
}

