const beforeCount = handleRequest({ method: 'GET', path: '/api/tasks', body: null }).body.length;
const result = handleRequest({ method: 'POST', path: '/api/tasks', body: { title: 'Learn React' } });
const afterCount = handleRequest({ method: 'GET', path: '/api/tasks', body: null }).body.length;
return result.status === 201 && result.body.title === 'Learn React' && result.body.done === false && result.body.id === beforeCount + 1 && afterCount === beforeCount + 1;

const before = handleRequest({ method: 'GET', path: '/api/tasks', body: null });
const result = handleRequest({ method: 'POST', path: '/api/tasks', body: { title: '   ' } });
const after = handleRequest({ method: 'GET', path: '/api/tasks', body: null });
return result.status === 400 && result.body.error === 'Title is required' && after.body.length === before.body.length;

const first = handleRequest({ method: 'POST', path: '/api/tasks', body: { title: 'First task' } });
const second = handleRequest({ method: 'POST', path: '/api/tasks', body: { title: 'Second task' } });
return second.status === 201 && second.body.id === first.body.id + 1 && second.body.title === 'Second task' && second.body.done === false;
